input.command:
cd /opt/bench/plugins/draftsman/skills/draftsman; WORK=/tmp/dm; cat > $WORK/view.json <<'EOF'
{
  "title": "Safelist and its direct relations",
  "focus": "org.jsoup.safety.Safelist",
  "hops": 1,
  "members": {"*": "none", "org.jsoup.safety.Safelist": "public"}
}
EOF
python3 scripts/render.py $WORK/ir.json $WORK/view.json -o $WORK/diagram.mmd && scripts/validate.sh $WORK/diagram.mmd; echo rc=$?; cat $WORK/diagram.mmd; python3 scripts/summary.py $WORK/ir.json | grep -A8 -i unresolved

